SELECT 
FROM t_ai_run r
LEFT JOIN t_ai_conversation c ON c.id = r.conversation_id
WHERE r.run_no = #{runNo}
  AND r.user_id = #{userId}

SELECT 
FROM t_ai_run r
LEFT JOIN t_ai_conversation c ON c.id = r.conversation_id
WHERE r.user_id = #{userId}
ORDER BY r.create_time DESC, r.id DESC
LIMIT #{offset}, #{limit}

SELECT COALESCE(MAX(turn_no), 0)
FROM t_ai_run
WHERE conversation_id = #{conversationId}
